const ELI_KINESTHETIC_HTML = "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n<meta charset=\"UTF-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n<title>Fraction Miner - Eli's Math Adventure</title>\n<style>\n  * { box-sizing: border-box; margin: 0; padding: 0; }\n\n  body {\n    background: #3E2723;\n    font-family: 'Courier New', monospace;\n    color: #F5F5DC;\n    min-height: 100vh;\n    background-image:\n      repeating-linear-gradient(0deg, transparent, transparent 31px, rgba(0,0,0,0.15) 31px, rgba(0,0,0,0.15) 32px),\n      repeating-linear-gradient(90deg, transparent, transparent 31px, rgba(0,0,0,0.15) 31px, rgba(0,0,0,0.15) 32px);\n  }\n\n  .game-header {\n    background: #4E342E;\n    border-bottom: 4px solid #1A1A1A;\n    padding: 12px 20px;\n    display: flex;\n    align-items: center;\n    justify-content: space-between;\n    image-rendering: pixelated;\n  }\n\n  .game-title {\n    font-size: 22px;\n    color: #8BC34A;\n    text-shadow: 3px 3px 0 #1A1A1A, -1px -1px 0 #1A1A1A;\n    letter-spacing: 2px;\n  }\n\n  .steve-icon {\n    width: 40px;\n    height: 40px;\n    background: #795548;\n    border: 3px solid #1A1A1A;\n    position: relative;\n    display: flex;\n    align-items: center;\n    justify-content: center;\n    font-size: 20px;\n  }\n\n  /* XP Bar */\n  .xp-container {\n    background: #2C1810;\n    border: 3px solid #1A1A1A;\n    padding: 6px 12px;\n    display: flex;\n    align-items: center;\n    gap: 10px;\n    margin: 0 20px;\n  }\n\n  .xp-label {\n    color: #FFD54F;\n    font-size: 12px;\n    white-space: nowrap;\n  }\n\n  .xp-bar-outer {\n    width: 160px;\n    height: 16px;\n    background: #1A1A1A;\n    border: 2px solid #5D4037;\n    position: relative;\n    overflow: hidden;\n  }\n\n  .xp-bar-inner {\n    height: 100%;\n    background: linear-gradient(90deg, #8BC34A, #CDDC39);\n    width: 0%;\n    transition: width 0.6s cubic-bezier(0.4, 0, 0.2, 1);\n    position: relative;\n  }\n\n  .xp-bar-inner::after {\n    content: '';\n    position: absolute;\n    top: 0; left: 0; right: 0; bottom: 0;\n    background: repeating-linear-gradient(90deg, transparent, transparent 6px, rgba(255,255,255,0.15) 6px, rgba(255,255,255,0.15) 8px);\n  }\n\n  /* Tabs */\n  .tabs {\n    display: flex;\n    border-bottom: 4px solid #1A1A1A;\n    background: #3E2723;\n  }\n\n  .tab-btn {\n    padding: 12px 20px;\n    background: #5D4037;\n    border: none;\n    border-right: 3px solid #1A1A1A;\n    color: #BCAAA4;\n    font-family: 'Courier New', monospace;\n    font-size: 13px;\n    cursor: pointer;\n    transition: background 0.1s;\n    letter-spacing: 1px;\n    position: relative;\n    image-rendering: pixelated;\n  }\n\n  .tab-btn:hover { background: #6D4C41; color: #FFF; }\n\n  .tab-btn.active {\n    background: #795548;\n    color: #8BC34A;\n    border-bottom: 4px solid #8BC34A;\n    margin-bottom: -4px;\n    font-weight: bold;\n  }\n\n  .tab-content {\n    display: none;\n    padding: 20px;\n    max-width: 800px;\n    margin: 0 auto;\n  }\n\n  .tab-content.active { display: block; }\n\n  /* Pixel border utility */\n  .pixel-box {\n    border: 4px solid #1A1A1A;\n    box-shadow: 4px 4px 0 #1A1A1A, inset 2px 2px 0 rgba(255,255,255,0.08);\n    image-rendering: pixelated;\n  }\n\n  /* ===== TAB 1: LEARN ===== */\n  .learn-step {\n    background: #4E342E;\n    padding: 18px;\n    margin-bottom: 16px;\n    border: 4px solid #1A1A1A;\n    box-shadow: 4px 4px 0 #1A1A1A;\n    display: none;\n    animation: slideIn 0.4s ease-out;\n  }\n\n  .learn-step.visible { display: block; }\n\n  @keyframes slideIn {\n    from { transform: translateY(-10px); opacity: 0; }\n    to { transform: translateY(0); opacity: 1; }\n  }\n\n  .step-title {\n    color: #FFD54F;\n    font-size: 15px;\n    margin-bottom: 12px;\n    border-bottom: 2px solid #795548;\n    padding-bottom: 6px;\n  }\n\n  .step-num {\n    background: #8BC34A;\n    color: #1A1A1A;\n    padding: 2px 8px;\n    margin-right: 8px;\n    font-weight: bold;\n    display: inline-block;\n    border: 2px solid #1A1A1A;\n  }\n\n  /* Fraction bars */\n  .bar-container {\n    margin: 12px 0;\n  }\n\n  .bar-label {\n    font-size: 13px;\n    color: #BCAAA4;\n    margin-bottom: 4px;\n  }\n\n  .fraction-bar-outer {\n    width: 100%;\n    height: 36px;\n    background: #1A1A1A;\n    border: 3px solid #5D4037;\n    position: relative;\n    overflow: hidden;\n  }\n\n  .fraction-bar-inner {\n    height: 100%;\n    transition: width 0.8s cubic-bezier(0.4, 0, 0.2, 1), background 0.5s;\n    position: relative;\n  }\n\n  .bar-grid {\n    position: absolute;\n    top: 0; left: 0; right: 0; bottom: 0;\n    display: flex;\n    pointer-events: none;\n  }\n\n  .bar-segment {\n    flex: 1;\n    border-right: 2px solid rgba(0,0,0,0.4);\n    transition: all 0.5s;\n  }\n\n  .bar-segment:last-child { border-right: none; }\n\n  .bar-segment.filled-green { background: #8BC34A; }\n  .bar-segment.filled-blue { background: #42A5F5; }\n  .bar-segment.filled-combined { background: #FF7043; }\n  .bar-segment.empty { background: #2C1810; }\n  .bar-segment.overflow-blink {\n    animation: overflowBlink 0.5s ease-in-out infinite alternate;\n  }\n\n  @keyframes overflowBlink {\n    from { background: #FF7043; }\n    to { background: #FFD54F; }\n  }\n\n  .fraction-display {\n    display: inline-block;\n    text-align: center;\n    font-size: 18px;\n    margin: 4px 10px;\n    vertical-align: middle;\n  }\n\n  .frac-num, .frac-den {\n    display: block;\n    line-height: 1.1;\n  }\n\n  .frac-line {\n    display: block;\n    width: 100%;\n    height: 2px;\n    background: #F5F5DC;\n    margin: 2px 0;\n  }\n\n  /* Speech bubble */\n  .speech-bubble {\n    background: #8BC34A;\n    color: #1A1A1A;\n    padding: 12px 16px;\n    border: 3px solid #1A1A1A;\n    box-shadow: 4px 4px 0 #1A1A1A;\n    position: relative;\n    margin: 16px 0;\n    font-size: 13px;\n    font-weight: bold;\n  }\n\n  .speech-bubble::before {\n    content: '🧑‍🔧 Steve:';\n    display: block;\n    font-size: 12px;\n    margin-bottom: 4px;\n    color: #1A1A1A;\n  }\n\n  .speech-bubble::after {\n    content: '';\n    position: absolute;\n    left: 20px;\n    bottom: -14px;\n    border: 7px solid transparent;\n    border-top-color: #1A1A1A;\n  }\n\n  /* Mine button */\n  .mine-btn {\n    background: #795548;\n    color: #F5F5DC;\n    border: 3px solid #1A1A1A;\n    box-shadow: 4px 4px 0 #1A1A1A;\n    padding: 12px 24px;\n    font-family: 'Courier New', monospace;\n    font-size: 14px;\n    cursor: pointer;\n    letter-spacing: 1px;\n    transition: transform 0.1s, box-shadow 0.1s;\n    display: block;\n    margin: 16px auto;\n  }\n\n  .mine-btn:hover { background: #8D6E63; }\n  .mine-btn:active { transform: translate(2px, 2px); box-shadow: 2px 2px 0 #1A1A1A; }\n  .mine-btn:disabled { opacity: 0.4; cursor: not-allowed; }\n\n  /* ===== TAB 2: EXPLORE ===== */\n  .explore-section {\n    background: #4E342E;\n    padding: 16px;\n    border: 4px solid #1A1A1A;\n    box-shadow: 4px 4px 0 #1A1A1A;\n    margin-bottom: 16px;\n  }\n\n  .explore-title {\n    color: #8BC34A;\n    font-size: 16px;\n    margin-bottom: 14px;\n    border-bottom: 2px solid #5D4037;\n    padding-bottom: 6px;\n  }\n\n  .fraction-builders {\n    display: grid;\n    grid-template-columns: 1fr 1fr;\n    gap: 16px;\n    margin-bottom: 16px;\n  }\n\n  .builder-card {\n    background: #3E2723;\n    border: 3px solid #5D4037;\n    padding: 14px;\n  }\n\n  .builder-title {\n    color: #FFD54F;\n    font-size: 13px;\n    margin-bottom: 10px;\n    text-align: center;\n  }\n\n  .slider-row {\n    margin-bottom: 10px;\n  }\n\n  .slider-row label {\n    font-size: 12px;\n    color: #BCAAA4;\n    display: block;\n    margin-bottom: 4px;\n  }\n\n  input[type=\"range\"] {\n    width: 100%;\n    height: 20px;\n    -webkit-appearance: none;\n    background: #1A1A1A;\n    border: 2px solid #5D4037;\n    outline: none;\n    cursor: pointer;\n  }\n\n  input[type=\"range\"]::-webkit-slider-thumb {\n    -webkit-appearance: none;\n    width: 20px;\n    height: 20px;\n    background: #8BC34A;\n    border: 3px solid #1A1A1A;\n    cursor: pointer;\n    image-rendering: pixelated;\n  }\n\n  .fraction-big {\n    text-align: center;\n    font-size: 32px;\n    color: #F5F5DC;\n    margin: 10px 0;\n    line-height: 1;\n  }\n\n  .fraction-big .fb-num { display: block; }\n  .fraction-big .fb-line { display: block; height: 3px; background: #F5F5DC; margin: 4px auto; width: 40px; }\n  .fraction-big .fb-den { display: block; }\n\n  .explore-bar-outer {\n    width: 100%;\n    height: 28px;\n    background: #1A1A1A;\n    border: 3px solid #5D4037;\n    position: relative;\n    overflow: visible;\n    margin-top: 8px;\n  }\n\n  .explore-bar-fill {\n    height: 100%;\n    background: #8BC34A;\n    transition: width 0.3s ease;\n    position: relative;\n    max-width: 100%;\n    overflow: hidden;\n  }\n\n  .explore-bar-fill.blue { background: #42A5F5; }\n\n  .overflow-indicator {\n    position: absolute;\n    right: -30px;\n    top: 0;\n    height: 100%;\n    background: #FF7043;\n    width: 0;\n    transition: width 0.3s;\n  }\n\n  .craft-btn {\n    background: linear-gradient(180deg, #8BC34A, #558B2F);\n    color: #1A1A1A;\n    border: 3px solid #1A1A1A;\n    box-shadow: 4px 4px 0 #1A1A1A;\n    padding: 12px 32px;\n    font-family: 'Courier New', monospace;\n    font-size: 15px;\n    cursor: pointer;\n    letter-spacing: 1px;\n    display: block;\n    margin: 14px auto;\n    transition: transform 0.1s, box-shadow 0.1s;\n    font-weight: bold;\n  }\n\n  .craft-btn:hover { filter: brightness(1.1); }\n  .craft-btn:active { transform: translate(2px, 2px); box-shadow: 2px 2px 0 #1A1A1A; }\n\n  .result-display {\n    background: #3E2723;\n    border: 3px solid #5D4037;\n    padding: 12px;\n    text-align: center;\n    min-height: 60px;\n    transition: all 0.3s;\n  }\n\n  .result-text {\n    font-size: 18px;\n    color: #FFD54F;\n  }\n\n  /* Block Challenge */\n  .challenge-box {\n    background: #3E2723;\n    border: 3px solid #FF7043;\n    padding: 14px;\n    margin-top: 16px;\n  }\n\n  .challenge-title {\n    color: #FF7043;\n    font-size: 14px;\n    margin-bottom: 10px;\n  }\n\n  .target-bar-outer {\n    width: 100%;\n    height: 32px;\n    background: #1A1A1A;\n    border: 3px solid #FF7043;\n    overflow: hidden;\n    margin-bottom: 10px;\n  }\n\n  .target-bar-fill {\n    height: 100%;\n    background: linear-gradient(90deg, #FF7043, #FF5722);\n    transition: width 0.4s;\n  }\n\n  .challenge-feedback {\n    font-size: 13px;\n    padding: 6px;\n    text-align: center;\n    margin-top: 6px;\n    min-height: 28px;\n    transition: all 0.3s;\n  }\n\n  @keyframes glowGreen {\n    0%, 100% { box-shadow: 0 0 8px #8BC34A, 0 0 20px #8BC34A; }\n    50% { box-shadow: 0 0 16px #8BC34A, 0 0 40px #8BC34A; }\n  }\n\n  @keyframes shakeAnim {\n    0%, 100% { transform: translateX(0); }\n    20% { transform: translateX(-6px); }\n    40% { transform: translateX(6px); }\n    60% { transform: translateX(-4px); }\n    80% { transform: translateX(4px); }\n  }\n\n  .glow-green { animation: glowGreen 1s ease-in-out infinite; border-color: #8BC34A !important; }\n  .shake { animation: shakeAnim 0.4s ease; }\n\n  /* ===== TAB 3: PRACTICE ===== */\n  .practice-problem {\n    display: none;\n    animation: slideIn 0.3s ease-out;\n  }\n  .practice-problem.active { display: block; }\n\n  .problem-header {\n    background: #4E342E;\n    border: 4px solid #1A1A1A;\n    box-shadow: 4px 4px 0 #1A1A1A;\n    padding: 16px;\n    margin-bottom: 14px;\n    text-align: center;\n  }\n\n  .problem-equation {\n    font-size: 26px;\n    color: #F5F5DC;\n    margin-bottom: 10px;\n  }\n\n  .problem-equation .frac-inline {\n    display: inline-flex;\n    flex-direction: column;\n    align-items: center;\n    vertical-align: middle;\n    font-size: 22px;\n    line-height: 1.1;\n    margin: 0 4px;\n  }\n\n  .problem-equation .frac-inline hr {\n    width: 100%;\n    border: 1px solid #F5F5DC;\n    margin: 2px 0;\n  }\n\n  .answer-blocks {\n    display: grid;\n    grid-template-columns: 1fr 1fr;\n    gap: 10px;\n    margin: 16px 0;\n  }\n\n  .answer-block {\n    background: #5D4037;\n    border: 4px solid #3E2723;\n    box-shadow: 4px 4px 0 #1A1A1A;\n    padding: 16px;\n    text-align: center;\n    cursor: pointer;\n    font-size: 20px;\n    color: #F5F5DC;\n    transition: background 0.15s, transform 0.1s;\n    font-family: 'Courier New', monospace;\n    display: flex;\n    align-items: center;\n    justify-content: center;\n  }\n\n  .answer-block:hover {\n    background: #6D4C41;\n    transform: translateY(-2px);\n    box-shadow: 4px 6px 0 #1A1A1A;\n  }\n\n  .answer-block:active { transform: translateY(0); }\n\n  .answer-block.correct {\n    background: #2E7D32 !important;\n    border-color: #8BC34A !important;\n    animation: glowGreen 0.8s ease-in-out;\n  }\n\n  .answer-block.wrong {\n    background: #B71C1C !important;\n    border-color: #FF5252 !important;\n    animation: shakeAnim 0.4s ease;\n  }\n\n  .answer-frac {\n    display: inline-flex;\n    flex-direction: column;\n    align-items: center;\n  }\n\n  .answer-frac span { display: block; line-height: 1.2; }\n  .answer-frac hr { width: 100%; border: 1.5px solid currentColor; margin: 2px 0; }\n\n  .feedback-msg {\n    text-align: center;\n    font-size: 16px;\n    padding: 10px;\n    min-height: 40px;\n    font-weight: bold;\n  }\n\n  .problem-bar-section {\n    background: #3E2723;\n    border: 3px solid #5D4037;\n    padding: 12px;\n    margin: 12px 0;\n  }\n\n  .prob-bar-label { font-size: 12px; color: #BCAAA4; margin-bottom: 4px; }\n  .prob-bar-outer {\n    width: 100%;\n    height: 28px;\n    background: #1A1A1A;\n    border: 2px solid #5D4037;\n    overflow: hidden;\n    margin-bottom: 6px;\n    position: relative;\n  }\n\n  .prob-bar-fill {\n    height: 100%;\n    transition: width 0.5s;\n  }\n\n  /* Progress tracker */\n  .progress-tracker {\n    display: flex;\n    gap: 8px;\n    justify-content: center;\n    margin-bottom: 14px;\n  }\n\n  .progress-dot {\n    width: 20px;\n    height: 20px;\n    background: #3E2723;\n    border: 3px solid #5D4037;\n    transition: background 0.3s, border-color 0.3s;\n  }\n\n  .progress-dot.done { background: #8BC34A; border-color: #8BC34A; }\n  .progress-dot.current { background: #FFD54F; border-color: #FFD54F; }\n  .progress-dot.wrong-dot { background: #FF5252; border-color: #FF5252; }\n\n  /* Confetti */\n  .confetti-container {\n    position: fixed;\n    top: 0; left: 0; right: 0; bottom: 0;\n    pointer-events: none;\n    z-index: 9999;\n    overflow: hidden;\n  }\n\n  .confetti-piece {\n    position: absolute;\n    width: 12px;\n    height: 12px;\n    top: -20px;\n    animation: confettiFall linear forwards;\n    image-rendering: pixelated;\n  }\n\n  @keyframes confettiFall {\n    0% { top: -20px; transform: rotate(0deg) scale(1); opacity: 1; }\n    80% { opacity: 1; }\n    100% { top: 110vh; transform: rotate(720deg) scale(0.5); opacity: 0; }\n  }\n\n  .level-up-banner {\n    position: fixed;\n    top: 50%;\n    left: 50%;\n    transform: translate(-50%, -50%) scale(0);\n    background: #8BC34A;\n    border: 6px solid #1A1A1A;\n    box-shadow: 8px 8px 0 #1A1A1A;\n    padding: 30px 50px;\n    z-index: 10000;\n    text-align: center;\n    animation: levelUpAnim 0.5s cubic-bezier(0.175, 0.885, 0.32, 1.275) 0.2s forwards;\n  }\n\n  @keyframes levelUpAnim {\n    from { transform: translate(-50%, -50%) scale(0); }\n    to { transform: translate(-50%, -50%) scale(1); }\n  }\n\n  .level-up-text {\n    font-size: 36px;\n    color: #1A1A1A;\n    font-weight: bold;\n    text-shadow: 3px 3px 0 rgba(0,0,0,0.2);\n    letter-spacing: 3px;\n  }\n\n  .level-up-sub {\n    font-size: 16px;\n    color: #3E2723;\n    margin-top: 8px;\n  }\n\n  .close-banner-btn {\n    background: #1A1A1A;\n    color: #8BC34A;\n    border: 3px solid #8BC34A;\n    padding: 8px 24px;\n    margin-top: 16px;\n    font-family: 'Courier New', monospace;\n    font-size: 14px;\n    cursor: pointer;\n  }\n\n  /* LCD steps animation */\n  .lcd-steps {\n    background: #2C1810;\n    border: 2px solid #5D4037;\n    padding: 10px;\n    margin: 10px 0;\n    font-size: 13px;\n    min-height: 50px;\n  }\n\n  .lcd-step-line {\n    opacity: 0;\n    transition: opacity 0.3s;\n    line-height: 1.8;\n    color: #BCAAA4;\n  }\n\n  .lcd-step-line.show { opacity: 1; }\n  .lcd-step-line .highlight { color: #FFD54F; }\n  .lcd-step-line .green { color: #8BC34A; }\n\n  /* Scrollbar */\n  ::-webkit-scrollbar { width: 8px; }\n  ::-webkit-scrollbar-track { background: #2C1810; }\n  ::-webkit-scrollbar-thumb { background: #5D4037; border: 1px solid #1A1A1A; }\n\n  .new-challenge-btn {\n    background: #FF7043;\n    color: #1A1A1A;\n    border: 3px solid #1A1A1A;\n    box-shadow: 3px 3px 0 #1A1A1A;\n    padding: 8px 18px;\n    font-family: 'Courier New', monospace;\n    font-size: 13px;\n    cursor: pointer;\n    margin-top: 8px;\n    font-weight: bold;\n  }\n\n  .new-challenge-btn:hover { filter: brightness(1.1); }\n\n  .challenge-slider-row {\n    display: flex;\n    align-items: center;\n    gap: 10px;\n    margin-bottom: 8px;\n  }\n\n  .challenge-slider-row label { font-size: 12px; color: #BCAAA4; min-width: 80px; }\n  .challenge-slider-row input { flex: 1; }\n  .challenge-slider-row .val { color: #FFD54F; min-width: 30px; text-align: right; font-size: 14px; }\n\n  .c-frac-display {\n    text-align: center;\n    font-size: 24px;\n    color: #F5F5DC;\n    margin: 8px 0;\n  }\n</style>\n</head>\n<body>\n\n<div class=\"game-header\">\n  <div class=\"steve-icon\">⛏</div>\n  <div class=\"game-title\">⬛ FRACTION MINER ⬛</div>\n  <div class=\"xp-container pixel-box\">\n    <span class=\"xp-label\">XP:</span>\n    <div class=\"xp-bar-outer\">\n      <div class=\"xp-bar-inner\" id=\"xpBar\"></div>\n    </div>\n    <span class=\"xp-label\" id=\"xpText\">0/5</span>\n  </div>\n</div>\n\n<div class=\"tabs\">\n  <button class=\"tab-btn active\" onclick=\"switchTab('learn')\">⛏ LEARN</button>\n  <button class=\"tab-btn\" onclick=\"switchTab('explore')\">🎮 EXPLORE</button>\n  <button class=\"tab-btn\" onclick=\"switchTab('practice')\">⚔ PRACTICE</button>\n</div>\n\n<!-- ===== TAB 1: LEARN ===== -->\n<div id=\"tab-learn\" class=\"tab-content active\">\n\n  <div class=\"speech-bubble\">\n    Every block matters in Minecraft, and every piece matters in fractions! Let's learn to add 4/5 + 1/3 together!\n  </div>\n\n  <!-- Step 1 -->\n  <div class=\"learn-step visible\" id=\"step1\">\n    <div class=\"step-title\"><span class=\"step-num\">1</span>Meet Our Fractions</div>\n    <p style=\"font-size:13px; color:#BCAAA4; margin-bottom:12px;\">We want to add 4/5 and 1/3. Let's see what they look like as bars!</p>\n    <div class=\"bar-container\">\n      <div class=\"bar-label\">Fraction 1: <strong style=\"color:#8BC34A\">4/5</strong> (4 out of 5 blocks filled)</div>\n      <div class=\"fraction-bar-outer\">\n        <div class=\"bar-grid\" id=\"bar1-grid\"></div>\n      </div>\n    </div>\n    <div class=\"bar-container\" style=\"margin-top:14px\">\n      <div class=\"bar-label\">Fraction 2: <strong style=\"color:#42A5F5\">1/3</strong> (1 out of 3 blocks filled)</div>\n      <div class=\"fraction-bar-outer\">\n        <div class=\"bar-grid\" id=\"bar2-grid\"></div>\n      </div>\n    </div>\n    <div style=\"text-align:center; margin-top:12px; font-size:20px; color:#F5F5DC;\">\n      <span style=\"display:inline-flex; flex-direction:column; align-items:center; vertical-align:middle;\">\n        <span style=\"color:#8BC34A\">4</span>\n        <span style=\"display:block; width:24px; height:2px; background:#F5F5DC; margin:2px auto;\"></span>\n        <span style=\"color:#8BC34A\">5</span>\n      </span>\n      &nbsp;+&nbsp;\n      <span style=\"display:inline-flex; flex-direction:column; align-items:center; vertical-align:middle;\">\n        <span style=\"color:#42A5F5\">1</span>\n        <span style=\"display:block; width:24px; height:2px; background:#F5F5DC; margin:2px auto;\"></span>\n        <span style=\"color:#42A5F5\">3</span>\n      </span>\n      &nbsp;= ?\n    </div>\n  </div>\n\n  <!-- Step 2 -->\n  <div class=\"learn-step\" id=\"step2\">\n    <div class=\"step-title\"><span class=\"step-num\">2</span>Find the LCD (Least Common Denominator)</div>\n    <p style=\"font-size:13px; color:#BCAAA4; margin-bottom:10px;\">Before we can add, we need the same size blocks! Multiples of 5: 5, 10, <strong style=\"color:#FFD54F\">15</strong>... Multiples of 3: 3, 6, 9, 12, <strong style=\"color:#FFD54F\">15</strong>...</p>\n    <div style=\"background:#3E2723; border: 3px solid #5D4037; padding:12px; text-align:center; font-size:18px; margin:10px 0;\">\n      LCD of 5 and 3 = <strong style=\"color:#FFD54F; font-size:24px;\">15</strong>\n    </div>\n    <p style=\"font-size:13px; color:#BCAAA4;\">We'll cut each bar into <strong style=\"color:#FFD54F\">15</strong> equal pieces — like 15 blocks in a Minecraft row!</p>\n    <div style=\"display:flex; gap:10px; justify-content:center; margin:12px 0; flex-wrap:wrap;\">\n      <div style=\"background:#5D4037; border:3px solid #1A1A1A; padding:8px 16px; text-align:center; font-size:13px;\">\n        5 × <span style=\"color:#FFD54F\">3</span> = 15\n      </div>\n      <div style=\"background:#5D4037; border:3px solid #1A1A1A; padding:8px 16px; text-align:center; font-size:13px;\">\n        3 × <span style=\"color:#FFD54F\">5</span> = 15\n      </div>\n    </div>\n  </div>\n\n  <!-- Step 3 -->\n  <div class=\"learn-step\" id=\"step3\">\n    <div class=\"step-title\"><span class=\"step-num\">3</span>Convert Both Fractions to /15</div>\n    <p style=\"font-size:13px; color:#BCAAA4; margin-bottom:10px;\">Multiply top and bottom by the same number:</p>\n    <div style=\"display:grid; grid-template-columns:1fr 1fr; gap:12px; margin-bottom:14px;\">\n      <div style=\"background:#3E2723; border:3px solid #5D4037; padding:10px; text-align:center; font-size:13px;\">\n        <div style=\"color:#8BC34A; margin-bottom:6px;\">4/5 → ?/15</div>\n        <div>4 × 3 = <span style=\"color:#FFD54F\">12</span></div>\n        <div>5 × 3 = 15</div>\n        <div style=\"margin-top:6px; font-size:16px; color:#8BC34A; font-weight:bold;\">= 12/15</div>\n      </div>\n      <div style=\"background:#3E2723; border:3px solid #5D4037; padding:10px; text-align:center; font-size:13px;\">\n        <div style=\"color:#42A5F5; margin-bottom:6px;\">1/3 → ?/15</div>\n        <div>1 × 5 = <span style=\"color:#FFD54F\">5</span></div>\n        <div>3 × 5 = 15</div>\n        <div style=\"margin-top:6px; font-size:16px; color:#42A5F5; font-weight:bold;\">= 5/15</div>\n      </div>\n    </div>\n    <div class=\"bar-container\">\n      <div class=\"bar-label\">4/5 = <strong style=\"color:#8BC34A\">12/15</strong> (now 15 blocks, 12 filled)</div>\n      <div class=\"fraction-bar-outer\">\n        <div class=\"bar-grid\" id=\"bar3-grid\"></div>\n      </div>\n    </div>\n    <div class=\"bar-container\" style=\"margin-top:10px;\">\n      <div class=\"bar-label\">1/3 = <strong style=\"color:#42A5F5\">5/15</strong> (now 15 blocks, 5 filled)</div>\n      <div class=\"fraction-bar-outer\">\n        <div class=\"bar-grid\" id=\"bar4-grid\"></div>\n      </div>\n    </div>\n  </div>\n\n  <!-- Step 4 -->\n  <div class=\"learn-step\" id=\"step4\">\n    <div class=\"step-title\"><span class=\"step-num\">4</span>Add Them Together!</div>\n    <p style=\"font-size:13px; color:#BCAAA4; margin-bottom:10px;\">12/15 + 5/15 = 17/15! Same denominator, just add the tops!</p>\n    <div style=\"text-align:center; font-size:22px; margin:12px 0; color:#F5F5DC;\">\n      <span style=\"color:#8BC34A\">12/15</span> + <span style=\"color:#42A5F5\">5/15</span> = <span style=\"color:#FF7043; font-size:28px; font-weight:bold;\">17/15</span>\n    </div>\n    <div class=\"bar-container\">\n      <div class=\"bar-label\" style=\"color:#FF7043;\"><strong>17/15</strong> — More than 1 whole! (OVERFLOW!)</div>\n      <div class=\"fraction-bar-outer\" style=\"border-color:#FF7043; overflow:visible; position:relative;\">\n        <div class=\"bar-grid\" id=\"bar5-grid\" style=\"width:100%; position:absolute;\"></div>\n        <div id=\"overflow-extra\" style=\"position:absolute; right:-60px; top:0; height:100%; width:0; background:#FF7043; transition:width 1s; border:2px solid #1A1A1A; display:flex; align-items:center; justify-content:center; font-size:11px; color:#1A1A1A; font-weight:bold; overflow:hidden;\">+2/15</div>\n      </div>\n    </div>\n    <div style=\"margin-top:50px; background:#3E2723; border:3px solid #8BC34A; padding:12px; text-align:center;\">\n      <div style=\"font-size:14px; color:#BCAAA4; margin-bottom:6px;\">As a mixed number:</div>\n      <div style=\"font-size:24px; color:#8BC34A; font-weight:bold;\">17/15 = 1 and 2/15</div>\n      <div style=\"font-size:12px; color:#BCAAA4; margin-top:4px;\">One full bar + 2 extra pieces!</div>\n    </div>\n    <div class=\"speech-bubble\" style=\"margin-top:20px;\">\n      Amazing work, miner! You just added fractions like a pro! 17 blocks total, 15 fill one row and 2 overflow into a new one! Just like Minecraft stacks!\n    </div>\n  </div>\n\n  <button class=\"mine-btn\" id=\"mineBtn\" onclick=\"mineNextBlock()\">Mine Next Block ⛏</button>\n</div>\n\n<!-- ===== TAB 2: EXPLORE ===== -->\n<div id=\"tab-explore\" class=\"tab-content\">\n\n  <div class=\"explore-section\">\n    <div class=\"explore-title\">⚒ FRACTION BUILDER</div>\n\n    <div class=\"fraction-builders\">\n      <!-- Builder 1 -->\n      <div class=\"builder-card\">\n        <div class=\"builder-title\" style=\"color:#8BC34A\">Fraction A (Green)</div>\n        <div class=\"slider-row\">\n          <label>Numerator: <span id=\"a-num-val\" style=\"color:#FFD54F\">3</span></label>\n          <input type=\"range\" min=\"0\" max=\"12\" value=\"3\" id=\"sliderAN\" oninput=\"updateBuilders()\">\n        </div>\n        <div class=\"slider-row\">\n          <label>Denominator: <span id=\"a-den-val\" style=\"color:#FFD54F\">4</span></label>\n          <input type=\"range\" min=\"1\" max=\"12\" value=\"4\" id=\"sliderAD\" oninput=\"updateBuilders()\">\n        </div>\n        <div class=\"fraction-big\" id=\"fracA-display\">\n          <span class=\"fb-num\">3</span>\n          <span class=\"fb-line\"></span>\n          <span class=\"fb-den\">4</span>\n        </div>\n        <div class=\"explore-bar-outer\">\n          <div class=\"explore-bar-fill\" id=\"barA-fill\" style=\"width:75%\"></div>\n        </div>\n      </div>\n\n      <!-- Builder 2 -->\n      <div class=\"builder-card\">\n        <div class=\"builder-title\" style=\"color:#42A5F5\">Fraction B (Blue)</div>\n        <div class=\"slider-row\">\n          <label>Numerator: <span id=\"b-num-val\" style=\"color:#FFD54F\">1</span></label>\n          <input type=\"range\" min=\"0\" max=\"12\" value=\"1\" id=\"sliderBN\" oninput=\"updateBuilders()\">\n        </div>\n        <div class=\"slider-row\">\n          <label>Denominator: <span id=\"b-den-val\" style=\"color:#FFD54F\">3</span></label>\n          <input type=\"range\" min=\"1\" max=\"12\" value=\"3\" id=\"sliderBD\" oninput=\"updateBuilders()\">\n        </div>\n        <div class=\"fraction-big\" id=\"fracB-display\">\n          <span class=\"fb-num\">1</span>\n          <span class=\"fb-line\"></span>\n          <span class=\"fb-den\">3</span>\n        </div>\n        <div class=\"explore-bar-outer\">\n          <div class=\"explore-bar-fill blue\" id=\"barB-fill\" style=\"width:33%\"></div>\n        </div>\n      </div>\n    </div>\n\n    <button class=\"craft-btn\" onclick=\"craftSum()\">⚒ Craft Sum +</button>\n\n    <div class=\"lcd-steps\" id=\"lcdSteps\">\n      <div style=\"color:#5D4037; font-size:12px; text-align:center;\">[ Press CRAFT SUM to see the magic! ]</div>\n    </div>\n\n    <div class=\"result-display\" id=\"resultDisplay\">\n      <div style=\"color:#5D4037; font-size:13px;\">Result will appear here...</div>\n    </div>\n  </div>\n\n  <!-- Block Challenge -->\n  <div class=\"explore-section\">\n    <div class=\"explore-title\" style=\"color:#FF7043;\">⚔ BLOCK CHALLENGE</div>\n    <p style=\"font-size:13px; color:#BCAAA4; margin-bottom:12px;\">Match the target fraction bar using the sliders below!</p>\n\n    <div class=\"challenge-box\" id=\"challengeBox\">\n      <div class=\"challenge-title\">🎯 TARGET FRACTION: <span id=\"targetFracDisplay\" style=\"color:#FFD54F\">?</span></div>\n      <div class=\"target-bar-outer\">\n        <div class=\"target-bar-fill\" id=\"targetBarFill\" style=\"width:60%\"></div>\n      </div>\n\n      <div class=\"challenge-slider-row\">\n        <label>Numerator:</label>\n        <input type=\"range\" min=\"0\" max=\"12\" value=\"1\" id=\"cSliderN\" oninput=\"checkChallenge()\">\n        <span class=\"val\" id=\"cNumVal\">1</span>\n      </div>\n      <div class=\"challenge-slider-row\">\n        <label>Denominator:</label>\n        <input type=\"range\" min=\"1\" max=\"12\" value=\"2\" id=\"cSliderD\" oninput=\"checkChallenge()\">\n        <span class=\"val\" id=\"cDenVal\">2</span>\n      </div>\n\n      <div class=\"c-frac-display\" id=\"cFracDisplay\">1/2</div>\n\n      <div class=\"challenge-bar-outer\" style=\"width:100%; height:28px; background:#1A1A1A; border:3px solid #5D4037; overflow:hidden; margin-bottom:8px;\">\n        <div id=\"challengeUserBar\" style=\"height:100%; background:#8BC34A; width:50%; transition:width 0.3s;\"></div>\n      </div>\n\n      <div class=\"challenge-feedback\" id=\"challengeFeedback\"></div>\n      <button class=\"new-challenge-btn\" onclick=\"newChallenge()\">🎲 New Challenge</button>\n    </div>\n  </div>\n</div>\n\n<!-- ===== TAB 3: PRACTICE ===== -->\n<div id=\"tab-practice\" class=\"tab-content\">\n\n  <div class=\"progress-tracker\" id=\"progressTracker\">\n    <div class=\"progress-dot current\" id=\"dot0\"></div>\n    <div class=\"progress-dot\" id=\"dot1\"></div>\n    <div class=\"progress-dot\" id=\"dot2\"></div>\n    <div class=\"progress-dot\" id=\"dot3\"></div>\n    <div class=\"progress-dot\" id=\"dot4\"></div>\n  </div>\n\n  <!-- Problem 1 -->\n  <div class=\"practice-problem active\" id=\"prob0\">\n    <div class=\"problem-header\">\n      <div style=\"font-size:13px; color:#BCAAA4; margin-bottom:6px;\">QUESTION 1 of 5</div>\n      <div class=\"problem-equation\">\n        <span class=\"frac-inline\"><span>4</span><hr/><span>5</span></span>\n        &nbsp;+&nbsp;\n        <span class=\"frac-inline\"><span>1</span><hr/><span>3</span></span>\n        &nbsp;= ?\n      </div>\n      <div class=\"problem-bar-section\">\n        <div class=\"prob-bar-label\">4/5</div>\n        <div class=\"prob-bar-outer\"><div class=\"prob-bar-fill\" style=\"width:80%; background:#8BC34A;\"></div></div>\n        <div class=\"prob-bar-label\">1/3</div>\n        <div class=\"prob-bar-outer\"><div class=\"prob-bar-fill\" style=\"width:33.3%; background:#42A5F5;\"></div></div>\n      </div>\n    </div>\n    <div class=\"answer-blocks\">\n      <div class=\"answer-block\" onclick=\"checkAnswer(this, false, 0)\"><span class=\"answer-frac\"><span>5</span><hr/><span>8</span></span></div>\n      <div class=\"answer-block\" onclick=\"checkAnswer(this, true, 0)\"><span class=\"answer-frac\"><span>17</span><hr/><span>15</span></span></div>\n      <div class=\"answer-block\" onclick=\"checkAnswer(this, false, 0)\"><span class=\"answer-frac\"><span>12</span><hr/><span>15</span></span></div>\n      <div class=\"answer-block\" onclick=\"checkAnswer(this, false, 0)\"><span class=\"answer-frac\"><span>7</span><hr/><span>15</span></span></div>\n    </div>\n    <div class=\"feedback-msg\" id=\"feedback0\"></div>\n  </div>\n\n  <!-- Problem 2 -->\n  <div class=\"practice-problem\" id=\"prob1\">\n    <div class=\"problem-header\">\n      <div style=\"font-size:13px; color:#BCAAA4; margin-bottom:6px;\">QUESTION 2 of 5</div>\n      <div class=\"problem-equation\">\n        <span class=\"frac-inline\"><span>2</span><hr/><span>7</span></span>\n        &nbsp;+&nbsp;\n        <span class=\"frac-inline\"><span>3</span><hr/><span>4</span></span>\n        &nbsp;= ?\n      </div>\n      <div class=\"problem-bar-section\">\n        <div class=\"prob-bar-label\">2/7</div>\n        <div class=\"prob-bar-outer\"><div class=\"prob-bar-fill\" style=\"width:28.6%; background:#8BC34A;\"></div></div>\n        <div class=\"prob-bar-label\">3/4</div>\n        <div class=\"prob-bar-outer\"><div class=\"prob-bar-fill\" style=\"width:75%; background:#42A5F5;\"></div></div>\n      </div>\n    </div>\n    <div class=\"answer-blocks\">\n      <div class=\"answer-block\" onclick=\"checkAnswer(this, false, 1)\"><span class=\"answer-frac\"><span>5</span><hr/><span>11</span></span></div>\n      <div class=\"answer-block\" onclick=\"checkAnswer(this, true, 1)\"><span class=\"answer-frac\"><span>29</span><hr/><span>28</span></span></div>\n      <div class=\"answer-block\" onclick=\"checkAnswer(this, false, 1)\"><span class=\"answer-frac\"><span>23</span><hr/><span>28</span></span></div>\n      <div class=\"answer-block\" onclick=\"checkAnswer(this, false, 1)\"><span class=\"answer-frac\"><span>8</span><hr/><span>28</span></span></div>\n    </div>\n    <div class=\"feedback-msg\" id=\"feedback1\"></div>\n  </div>\n\n  <!-- Problem 3 -->\n  <div class=\"practice-problem\" id=\"prob2\">\n    <div class=\"problem-header\">\n      <div style=\"font-size:13px; color:#BCAAA4; margin-bottom:6px;\">QUESTION 3 of 5</div>\n      <div class=\"problem-equation\">\n        <span class=\"frac-inline\"><span>1</span><hr/><span>2</span></span>\n        &nbsp;+&nbsp;\n        <span class=\"frac-inline\"><span>2</span><hr/><span>3</span></span>\n        &nbsp;= ?\n      </div>\n      <div class=\"problem-bar-section\">\n        <div class=\"prob-bar-label\">1/2</div>\n        <div class=\"prob-bar-outer\"><div class=\"prob-bar-fill\" style=\"width:50%; background:#8BC34A;\"></div></div>\n        <div class=\"prob-bar-label\">2/3</div>\n        <div class=\"prob-bar-outer\"><div class=\"prob-bar-fill\" style=\"width:66.7%; background:#42A5F5;\"></div></div>\n      </div>\n    </div>\n    <div class=\"answer-blocks\">\n      <div class=\"answer-block\" onclick=\"checkAnswer(this, false, 2)\"><span class=\"answer-frac\"><span>3</span><hr/><span>5</span></span></div>\n      <div class=\"answer-block\" onclick=\"checkAnswer(this, false, 2)\"><span class=\"answer-frac\"><span>5</span><hr/><span>6</span></span></div>\n      <div class=\"answer-block\" onclick=\"checkAnswer(this, true, 2)\"><span class=\"answer-frac\"><span>7</span><hr/><span>6</span></span></div>\n      <div class=\"answer-block\" onclick=\"checkAnswer(this, false, 2)\"><span class=\"answer-frac\"><span>4</span><hr/><span>6</span></span></div>\n    </div>\n    <div class=\"feedback-msg\" id=\"feedback2\"></div>\n  </div>\n\n  <!-- Problem 4 -->\n  <div class=\"practice-problem\" id=\"prob3\">\n    <div class=\"problem-header\">\n      <div style=\"font-size:13px; color:#BCAAA4; margin-bottom:6px;\">QUESTION 4 of 5</div>\n      <div class=\"problem-equation\">\n        <span class=\"frac-inline\"><span>3</span><hr/><span>8</span></span>\n        &nbsp;+&nbsp;\n        <span class=\"frac-inline\"><span>1</span><hr/><span>4</span></span>\n        &nbsp;= ?\n      </div>\n      <div class=\"problem-bar-section\">\n        <div class=\"prob-bar-label\">3/8</div>\n        <div class=\"prob-bar-outer\"><div class=\"prob-bar-fill\" style=\"width:37.5%; background:#8BC34A;\"></div></div>\n        <div class=\"prob-bar-label\">1/4</div>\n        <div class=\"prob-bar-outer\"><div class=\"prob-bar-fill\" style=\"width:25%; background:#42A5F5;\"></div></div>\n      </div>\n    </div>\n    <div class=\"answer-blocks\">\n      <div class=\"answer-block\" onclick=\"checkAnswer(this, false, 3)\"><span class=\"answer-frac\"><span>4</span><hr/><span>12</span></span></div>\n      <div class=\"answer-block\" onclick=\"checkAnswer(this, true, 3)\"><span class=\"answer-frac\"><span>5</span><hr/><span>8</span></span></div>\n      <div class=\"answer-block\" onclick=\"checkAnswer(this, false, 3)\"><span class=\"answer-frac\"><span>4</span><hr/><span>8</span></span></div>\n      <div class=\"answer-block\" onclick=\"checkAnswer(this, false, 3)\"><span class=\"answer-frac\"><span>7</span><hr/><span>8</span></span></div>\n    </div>\n    <div class=\"feedback-msg\" id=\"feedback3\"></div>\n  </div>\n\n  <!-- Problem 5 -->\n  <div class=\"practice-problem\" id=\"prob4\">\n    <div class=\"problem-header\">\n      <div style=\"font-size:13px; color:#BCAAA4; margin-bottom:6px;\">QUESTION 5 of 5</div>\n      <div class=\"problem-equation\">\n        <span class=\"frac-inline\"><span>5</span><hr/><span>6</span></span>\n        &nbsp;+&nbsp;\n        <span class=\"frac-inline\"><span>1</span><hr/><span>2</span></span>\n        &nbsp;= ?\n      </div>\n      <div class=\"problem-bar-section\">\n        <div class=\"prob-bar-label\">5/6</div>\n        <div class=\"prob-bar-outer\"><div class=\"prob-bar-fill\" style=\"width:83.3%; background:#8BC34A;\"></div></div>\n        <div class=\"prob-bar-label\">1/2</div>\n        <div class=\"prob-bar-outer\"><div class=\"prob-bar-fill\" style=\"width:50%; background:#42A5F5;\"></div></div>\n      </div>\n    </div>\n    <div class=\"answer-blocks\">\n      <div class=\"answer-block\" onclick=\"checkAnswer(this, false, 4)\"><span class=\"answer-frac\"><span>6</span><hr/><span>8</span></span></div>\n      <div class=\"answer-block\" onclick=\"checkAnswer(this, false, 4)\"><span class=\"answer-frac\"><span>4</span><hr/><span>3</span></span></div>\n      <div class=\"answer-block\" onclick=\"checkAnswer(this, false, 4)\"><span class=\"answer-frac\"><span>7</span><hr/><span>6</span></span></div>\n      <div class=\"answer-block\" onclick=\"checkAnswer(this, true, 4)\"><span class=\"answer-frac\"><span>8</span><hr/><span>6</span></span></div>\n    </div>\n    <div class=\"feedback-msg\" id=\"feedback4\"></div>\n  </div>\n\n</div>\n\n<script>\n// ===== GLOBAL STATE =====\nvar currentStep = 1;\nvar totalSteps = 4;\nvar xpEarned = 0;\nvar currentProblem = 0;\nvar wrongCounts = [0, 0, 0, 0, 0];\nvar problemSolved = [false, false, false, false, false];\nvar problemTexts = [\n  '4/5 + 1/3 = ?',\n  '2/7 + 3/4 = ?',\n  '1/2 + 2/3 = ?',\n  '3/8 + 1/4 = ?',\n  '5/6 + 1/2 = ?'\n];\nvar targetNum = 3, targetDen = 5;\n\n// ===== TAB SWITCHING =====\nfunction switchTab(name) {\n  document.querySelectorAll('.tab-content').forEach(function(t) { t.classList.remove('active'); });\n  document.querySelectorAll('.tab-btn').forEach(function(b) { b.classList.remove('active'); });\n  document.getElementById('tab-' + name).classList.add('active');\n  event.target.classList.add('active');\n  if (name === 'explore') { initChallenge(); }\n}\n\n// ===== TAB 1: LEARN =====\nfunction buildBar(gridId, segments, filledCount, color) {\n  var grid = document.getElementById(gridId);\n  if (!grid) return;\n  grid.innerHTML = '';\n  for (var i = 0; i < segments; i++) {\n    var seg = document.createElement('div');\n    seg.className = 'bar-segment';\n    if (i < filledCount) {\n      seg.classList.add(color);\n      if (color === 'filled-combined' && i >= 15) {\n        seg.classList.add('overflow-blink');\n      }\n    } else {\n      seg.classList.add('empty');\n    }\n    grid.appendChild(seg);\n  }\n}\n\n// Initial bars on load\nwindow.addEventListener('load', function() {\n  buildBar('bar1-grid', 5, 4, 'filled-green');\n  buildBar('bar2-grid', 3, 1, 'filled-blue');\n  initChallenge();\n});\n\nfunction mineNextBlock() {\n  if (currentStep >= totalSteps) return;\n  currentStep++;\n\n  var step = document.getElementById('step' + currentStep);\n  if (step) {\n    step.classList.add('visible');\n    step.scrollIntoView({ behavior: 'smooth', block: 'start' });\n  }\n\n  if (currentStep === 3) {\n    setTimeout(function() {\n      buildBar('bar3-grid', 15, 12, 'filled-green');\n      buildBar('bar4-grid', 15, 5, 'filled-blue');\n    }, 300);\n  }\n\n  if (currentStep === 4) {\n    setTimeout(function() {\n      buildBar('bar5-grid', 15, 15, 'filled-combined');\n      setTimeout(function() {\n        var overflow = document.getElementById('overflow-extra');\n        if (overflow) { overflow.style.width = '55px'; }\n      }, 800);\n    }, 400);\n  }\n\n  if (currentStep >= totalSteps) {\n    document.getElementById('mineBtn').disabled = true;\n    document.getElementById('mineBtn').textContent = '✅ All Blocks Mined!';\n  }\n}\n\n// ===== TAB 2: EXPLORE =====\nfunction updateBuilders() {\n  var an = parseInt(document.getElementById('sliderAN').value);\n  var ad = parseInt(document.getElementById('sliderAD').value);\n  var bn = parseInt(document.getElementById('sliderBN').value);\n  var bd = parseInt(document.getElementById('sliderBD').value);\n\n  document.getElementById('a-num-val').textContent = an;\n  document.getElementById('a-den-val').textContent = ad;\n  document.getElementById('b-num-val').textContent = bn;\n  document.getElementById('b-den-val').textContent = bd;\n\n  // Update fraction displays\n  document.getElementById('fracA-display').innerHTML =\n    '<span class=\"fb-num\">' + an + '</span><span class=\"fb-line\"></span><span class=\"fb-den\">' + ad + '</span>';\n  document.getElementById('fracB-display').innerHTML =\n    '<span class=\"fb-num\">' + bn + '</span><span class=\"fb-line\"></span><span class=\"fb-den\">' + bd + '</span>';\n\n  // Update bars (cap at 100%)\n  var pctA = Math.min((an / ad) * 100, 100);\n  var pctB = Math.min((bn / bd) * 100, 100);\n  document.getElementById('barA-fill').style.width = pctA + '%';\n  document.getElementById('barB-fill').style.width = pctB + '%';\n}\n\nfunction gcd(a, b) {\n  a = Math.abs(a); b = Math.abs(b);\n  while (b) { var t = b; b = a % b; a = t; }\n  return a;\n}\n\nfunction lcm(a, b) {\n  return (a * b) / gcd(a, b);\n}\n\nfunction craftSum() {\n  var an = parseInt(document.getElementById('sliderAN').value);\n  var ad = parseInt(document.getElementById('sliderAD').value);\n  var bn = parseInt(document.getElementById('sliderBN').value);\n  var bd = parseInt(document.getElementById('sliderBD').value);\n\n  var lcd = lcm(ad, bd);\n  var newAN = an * (lcd / ad);\n  var newBN = bn * (lcd / bd);\n  var sumN = newAN + newBN;\n  var sumD = lcd;\n\n  var g = gcd(sumN, sumD);\n  var simplN = sumN / g;\n  var simplD = sumD / g;\n\n  var stepsEl = document.getElementById('lcdSteps');\n  stepsEl.innerHTML = '';\n\n  var lines = [\n    '<span class=\"highlight\">Step 1:</span> Find LCD of ' + ad + ' and ' + bd + ' = <span class=\"green\">' + lcd + '</span>',\n    '<span class=\"highlight\">Step 2:</span> Convert: <span class=\"green\">' + an + '/' + ad + ' → ' + newAN + '/' + lcd + '</span>  |  <span style=\"color:#42A5F5\">' + bn + '/' + bd + ' → ' + newBN + '/' + lcd + '</span>',\n    '<span class=\"highlight\">Step 3:</span> Add numerators: <span class=\"green\">' + newAN + ' + ' + newBN + ' = ' + sumN + '</span>',\n    '<span class=\"highlight\">Step 4:</span> Result = <span class=\"green\">' + sumN + '/' + sumD + '</span>' + (g > 1 ? ' = <span style=\"color:#FFD54F\">' + simplN + '/' + simplD + '</span> (simplified)' : '')\n  ];\n\n  lines.forEach(function(line, i) {\n    var div = document.createElement('div');\n    div.className = 'lcd-step-line';\n    div.innerHTML = line;\n    stepsEl.appendChild(div);\n    setTimeout(function() { div.classList.add('show'); }, i * 400);\n  });\n\n  setTimeout(function() {\n    var isOver = (sumN / sumD) > 1;\n    document.getElementById('resultDisplay').innerHTML =\n      '<div class=\"result-text\">' +\n      '<span style=\"color:#8BC34A\">' + an + '/' + ad + '</span> + <span style=\"color:#42A5F5\">' + bn + '/' + bd + '</span> = ' +\n      '<span style=\"color:#FF7043; font-size:24px;\">' + sumN + '/' + sumD + '</span>' +\n      (g > 1 ? ' = <span style=\"color:#FFD54F\">' + simplN + '/' + simplD + '</span>' : '') +\n      (isOver ? '<br><span style=\"color:#FFD54F; font-size:13px;\">⬛ More than 1 whole!</span>' : '') +\n      '</div>';\n  }, lines.length * 400 + 200);\n}\n\n// ===== BLOCK CHALLENGE =====\nfunction initChallenge() {\n  newChallenge();\n}\n\nfunction newChallenge() {\n  targetNum = Math.floor(Math.random() * 9) + 1;\n  targetDen = Math.floor(Math.random() * 8) + 2;\n  while (targetNum > targetDen) { targetNum = Math.floor(Math.random() * 9) + 1; }\n\n  document.getElementById('targetFracDisplay').textContent = targetNum + '/' + targetDen;\n  var pct = Math.min((targetNum / targetDen) * 100, 100);\n  document.getElementById('targetBarFill').style.width = pct + '%';\n\n  document.getElementById('challengeFeedback').textContent = '';\n  document.getElementById('challengeBox').classList.remove('glow-green', 'shake');\n\n  document.getElementById('cSliderN').value = 1;\n  document.getElementById('cSliderD').value = 2;\n  checkChallenge();\n}\n\nfunction checkChallenge() {\n  var cn = parseInt(document.getElementById('cSliderN').value);\n  var cd = parseInt(document.getElementById('cSliderD').value);\n\n  document.getElementById('cNumVal').textContent = cn;\n  document.getElementById('cDenVal').textContent = cd;\n  document.getElementById('cFracDisplay').textContent = cn + '/' + cd;\n\n  var userPct = Math.min((cn / cd) * 100, 100);\n  document.getElementById('challengeUserBar').style.width = userPct + '%';\n\n  var targetVal = targetNum / targetDen;\n  var userVal = cn / cd;\n  var tolerance = 0.01;\n\n  var box = document.getElementById('challengeBox');\n  var feedback = document.getElementById('challengeFeedback');\n  box.classList.remove('glow-green', 'shake');\n\n  if (Math.abs(userVal - targetVal) <= tolerance) {\n    void box.offsetWidth;\n    box.classList.add('glow-green');\n    feedback.innerHTML = '<span style=\"color:#8BC34A\">✅ PERFECT MATCH! You found ' + cn + '/' + cd + '!</span>';\n  } else {\n    var diff = Math.abs(userVal - targetVal);\n    if (diff < 0.1) {\n      feedback.innerHTML = '<span style=\"color:#FFD54F\">🔥 Very close! Keep adjusting!</span>';\n    } else {\n      feedback.innerHTML = '<span style=\"color:#BCAAA4\">Keep digging, miner! Try different numbers.</span>';\n    }\n  }\n}\n\n// ===== TAB 3: PRACTICE =====\nfunction checkAnswer(el, isCorrect, probIdx) {\n  if (problemSolved[probIdx]) return;\n\n  var blocks = el.closest('.answer-blocks');\n  if (!blocks) return;\n  var allBlocks = blocks.querySelectorAll('.answer-block');\n  allBlocks.forEach(function(b) { b.style.pointerEvents = 'none'; });\n\n  var feedback = document.getElementById('feedback' + probIdx);\n\n  if (isCorrect) {\n    el.classList.add('correct');\n    problemSolved[probIdx] = true;\n    feedback.innerHTML = '<span style=\"color:#8BC34A; font-size:18px;\">⛏ MINED IT! Excellent work!</span>';\n\n    xpEarned++;\n    updateXP();\n\n    setTimeout(function() {\n      advanceProblem(probIdx);\n    }, 1500);\n\n  } else {\n    el.classList.add('wrong');\n    wrongCounts[probIdx]++;\n\n    var remaining = 3 - wrongCounts[probIdx];\n\n    if (wrongCounts[probIdx] >= 3) {\n      feedback.innerHTML = '<span style=\"color:#FF7043;\">Need help? Check the LEARN tab! Try again!</span>';\n\n      try {\n        window.parent.postMessage({\n          type: 'wrongAnswer',\n          questionText: problemTexts[probIdx],\n          wrongCount: 3\n        }, '*');\n        window.parent.postMessage({\n          type: 'reframeNeeded',\n          questionText: problemTexts[probIdx]\n        }, '*');\n      } catch(e) {}\n\n      setTimeout(function() {\n        el.classList.remove('wrong');\n        allBlocks.forEach(function(b) {\n          b.classList.remove('wrong');\n          b.style.pointerEvents = 'auto';\n        });\n        wrongCounts[probIdx] = 0;\n        feedback.innerHTML = '';\n      }, 1800);\n    } else {\n      feedback.innerHTML = '<span style=\"color:#FF7043;\">Try again, miner! (' + remaining + ' tries left)</span>';\n      setTimeout(function() {\n        el.classList.remove('wrong');\n        allBlocks.forEach(function(b) { b.style.pointerEvents = 'auto'; });\n        el.style.pointerEvents = 'none';\n      }, 700);\n    }\n  }\n}\n\nfunction advanceProblem(probIdx) {\n  var dot = document.getElementById('dot' + probIdx);\n  if (dot) { dot.classList.remove('current'); dot.classList.add('done'); }\n\n  if (probIdx < 4) {\n    document.getElementById('prob' + probIdx).classList.remove('active');\n    currentProblem = probIdx + 1;\n    document.getElementById('prob' + currentProblem).classList.add('active');\n    var nextDot = document.getElementById('dot' + currentProblem);\n    if (nextDot) { nextDot.classList.add('current'); }\n    document.getElementById('prob' + currentProblem).scrollIntoView({ behavior: 'smooth', block: 'start' });\n  } else {\n    // All done!\n    setTimeout(function() {\n      showLevelUp();\n    }, 300);\n  }\n}\n\nfunction updateXP() {\n  var pct = (xpEarned / 5) * 100;\n  document.getElementById('xpBar').style.width = pct + '%';\n  document.getElementById('xpText').textContent = xpEarned + '/5';\n}\n\n// ===== LEVEL UP & CONFETTI =====\nfunction showLevelUp() {\n  launchConfetti();\n\n  var banner = document.createElement('div');\n  banner.className = 'level-up-banner';\n  banner.innerHTML =\n    '<div class=\"level-up-text\">🏆 LEVEL UP! 🏆</div>' +\n    '<div class=\"level-up-sub\">You mined all 5 fraction problems!</div>' +\n    '<div style=\"font-size:32px; margin:12px 0;\">⛏ ⬛ ⛏</div>' +\n    '<div style=\"font-size:14px; color:#1A1A1A; margin-bottom:8px;\">Eli is a Fraction Mining Master!</div>' +\n    '<button class=\"close-banner-btn\" onclick=\"closeBanner(this.parentElement)\">Keep Mining!</button>';\n  document.body.appendChild(banner);\n}\n\nfunction closeBanner(el) {\n  el.remove();\n  var confContainer = document.getElementById('confettiContainer');\n  if (confContainer) confContainer.remove();\n}\n\nfunction launchConfetti() {\n  var container = document.createElement('div');\n  container.className = 'confetti-container';\n  container.id = 'confettiContainer';\n  document.body.appendChild(container);\n\n  var colors = ['#8BC34A', '#42A5F5', '#FF7043', '#FFD54F', '#795548', '#E91E63', '#00BCD4'];\n  var emojis = ['⬛', '🟩', '🟦', '🟧'];\n\n  for (var i = 0; i < 60; i++) {\n    (function(i) {\n      setTimeout(function() {\n        var piece = document.createElement('div');\n        piece.className = 'confetti-piece';\n        piece.style.left = Math.random() * 100 + 'vw';\n        piece.style.animationDuration = (2 + Math.random() * 3) + 's';\n        piece.style.animationDelay = Math.random() * 0.5 + 's';\n\n        if (Math.random() > 0.5) {\n          piece.style.background = colors[Math.floor(Math.random() * colors.length)];\n          piece.style.borderRadius = Math.random() > 0.5 ? '0' : '50%';\n        } else {\n          piece.textContent = emojis[Math.floor(Math.random() * emojis.length)];\n          piece.style.background = 'transparent';\n          piece.style.fontSize = '16px';\n        }\n\n        container.appendChild(piece);\n\n        piece.addEventListener('animationend', function() {\n          piece.remove();\n        });\n      }, i * 50);\n    })(i);\n  }\n}\n\n// Initialize\nupdateBuilders();\n</script>\n</body>\n</html>";

